/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, ScanError, KINDS } from './scanner.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function body(token) {
  return token.kind === 'string' || token.kind === 'rawstring' ? JSON.stringify(token.text) : token.text
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'tokens' && mode !== 'stats')) fail('usage: cli.js tokens|stats')

  let tokens
  try {
    tokens = scan(readStdin())
  } catch (error) {
    if (error instanceof ScanError) fail(`${error.line}:${error.column}: ${error.reason}`)
    throw error
  }

  let out = ''
  if (mode === 'tokens') {
    for (const token of tokens) out += `${token.line}:${token.column} ${token.kind} ${body(token)}\n`
  } else {
    for (const kind of KINDS) out += `${kind} ${tokens.filter((t) => t.kind === kind).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

main(process.argv.slice(2))
